INSERT INTO public.posts (id, user_id, title, description, single_image_url, images, likes_count, comments_count, shares_count, is_sponsored, post_type, city, created_at, updated_at) VALUES ('2ea6a8ef-7393-5bc9-8d30-2a713690999c'::uuid, '95c9cdbe-e880-5ce3-8319-88a44f7439ac'::uuid, '', 'Le siège de bureaux conçu pour BMCE à Casablanca réunit environ 6 000 m² sur 26 m de haut. Le bâtiment compte dix niveaux : deux sous-sols, un rez-de-chaussée et sept étages.

Les sous-sols accueillent le parking, les locaux techniques et les archives. Le rez-de-chaussée rassemble l''accueil, les salles de réunion, la cafétéria, le fitness et la maintenance. La façade associe verre, inox, alucobond et ardoise agrafée. La maîtrise d''œuvre est celle de CHB Architects, le cabinet de Hakim Benjelloun, au 2, rue des Moineaux.', 'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&w=1600&q=80', '["https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&w=1600&q=80", "https://images.unsplash.com/photo-1497366216548-37526070297c?auto=format&fit=crop&w=1600&q=80", "https://images.unsplash.com/photo-1497366811353-6870744d04b2?auto=format&fit=crop&w=1600&q=80", "https://images.unsplash.com/photo-1497366754035-f200968a6e72?auto=format&fit=crop&w=1600&q=80", "https://images.unsplash.com/photo-1524758631624-e2822e304c36?auto=format&fit=crop&w=1600&q=80"]'::jsonb, 0, 0, 0, FALSE, 'standard', 'Casablanca', '2026-09-28T09:30:00+00'::timestamptz, '2026-09-28T09:30:00+00'::timestamptz);
INSERT INTO public.posts (id, user_id, title, description, single_image_url, images, likes_count, comments_count, shares_count, is_sponsored, post_type, city, created_at, updated_at) VALUES ('18994937-11cc-51e2-8e92-1e9a87acab1c'::uuid, 'e5f9fff7-415f-5749-8468-151a926d4f4e'::uuid, '', 'Grand Théâtre de Casablanca (CasArts) : 24 000 m² au cœur du quartier historique, salle de spectacle 1 800 places, théâtre 600 places et salle de musique 450 places. TGCC a assuré une mission tous corps d''état pour Casa Aménagement.

Parmi nos autres références récentes : campus UM6P à Rabat (+100 000 m² couverts), trémie Dar Bouazza et stade Al Barid.', 'https://tgcc.ma/wp-content/uploads/2025/12/Grand_theatre.jpg', '["https://tgcc.ma/wp-content/uploads/2025/12/Grand_theatre.jpg", "https://tgcc.ma/wp-content/uploads/2025/12/TGCC-UM6P-RABAT_result.jpg", "https://tgcc.ma/wp-content/uploads/2025/12/Tremie-Dar-Bouazza-1_result.jpg", "https://tgcc.ma/wp-content/uploads/2026/01/STADE-AL-BARID-73-1_result.jpg"]'::jsonb, 0, 0, 0, FALSE, 'standard', 'Casablanca', '2026-09-20T11:00:00+00'::timestamptz, '2026-09-20T11:00:00+00'::timestamptz);
INSERT INTO public.posts (id, user_id, title, description, single_image_url, images, likes_count, comments_count, shares_count, is_sponsored, post_type, city, created_at, updated_at) VALUES ('04cd3978-b982-503a-a315-a689eff608c3'::uuid, 'cef92b70-9083-53cd-9f2d-ffb47877669e'::uuid, '', 'La Compagnie Générale Immobilière, filiale de la Caisse de Dépôt et de Gestion depuis 1960, développe et commercialise des programmes résidentiels et tertiaires sur l''ensemble du Maroc.

Le métier couvre le montage de l''opération, la mise en vente des lots (VEFA) et le suivi jusqu''à la livraison. Portefeuille recentré sur le moyen et haut standing et les projets mixtes : GreenSide, Azur Valley, Les Arborelles, Domaine de Noria, Taghazout Bay Living…', 'https://cdgdev.ma/sites/default/files/2025-03/Arborelles%20020624_3%20-%20Photo.jpg', '["https://cdgdev.ma/sites/default/files/2025-03/Arborelles%20020624_3%20-%20Photo.jpg", "https://cdgdev.ma/sites/default/files/2024-12/Casa%20Green%20Town%20_%20CASABLANCA-0082024_%C2%A9Said%20Mrigua_SAID%20MRIGUA%281%29.jpg", "https://cdgdev.ma/sites/default/files/2025-03/DPR-CGI-TAGHAZOUT-Bis-Oct-2024-920x860.png"]'::jsonb, 0, 0, 0, FALSE, 'standard', 'Casablanca', '2026-09-14T08:45:00+00'::timestamptz, '2026-09-14T08:45:00+00'::timestamptz);
INSERT INTO public.posts (id, user_id, title, description, single_image_url, images, likes_count, comments_count, shares_count, is_sponsored, post_type, city, created_at, updated_at) VALUES ('e05fbd86-e16d-519d-894a-8ffde2a927c9'::uuid, 'c9917c8b-b34c-5970-a885-abe9b157a66f'::uuid, '', 'Interstyle Design, cabinet fondé par Wafaa Elkass et installé à Massira, reprend les appartements à Casablanca à partir de 60 m². Les bureaux et les locaux sont étudiés au cas par cas.

Un seul interlocuteur coordonne les corps d''état, de la maçonnerie aux finitions : électricité, plomberie, revêtements et menuiseries. Conception 2D/3D, puis livraison clé en main — y compris pour les clients qui pilotent à distance.', 'https://interstyledesign.ma/images/projets/renovation-racine-01.webp', '["https://interstyledesign.ma/images/projets/renovation-racine-01.webp", "https://interstyledesign.ma/images/projets/renovation-racine-02.webp", "https://interstyledesign.ma/images/projets/renovation-racine-03.webp", "https://interstyledesign.ma/images/projets/aeria-hs-1.webp", "https://interstyledesign.ma/images/projets/aeria-hs-9.webp"]'::jsonb, 0, 0, 0, FALSE, 'standard', 'Casablanca', '2026-09-08T16:15:00+00'::timestamptz, '2026-09-08T16:15:00+00'::timestamptz);
INSERT INTO public.posts (id, user_id, title, description, single_image_url, images, likes_count, comments_count, shares_count, is_sponsored, post_type, city, created_at, updated_at) VALUES ('6b3f8959-bfa1-56f3-93d1-123c47a1928d'::uuid, '0c28bc7a-c563-5a3c-9d06-aee3467996c2'::uuid, '', 'BETAM (Bureau d''Études et d''Aménagement Maroc) assure depuis 1975 les études techniques et le suivi de réalisation pour des maîtres d''ouvrage publics et privés.

Références : aéroport de Fès-Saïss, infrastructures de Tan-Tan, port de Casablanca, centre hospitalier régional de Guelmim. Honoraires sur devis ; suivi possible à distance.', 'https://betam.ma/wp-content/uploads/2020/09/Un-service-batiment-genie-civil.jpg', '["https://betam.ma/wp-content/uploads/2020/09/Un-service-batiment-genie-civil.jpg", "https://betam.ma/wp-content/uploads/2020/10/etude-general.jpg", "https://betam.ma/wp-content/uploads/2020/10/maitrise-doeuvre.jpg", "https://betam.ma/wp-content/uploads/2020/10/Assistance-Maitrise-douvrage.jpg"]'::jsonb, 0, 0, 0, FALSE, 'standard', 'Casablanca', '2026-08-27T10:00:00+00'::timestamptz, '2026-08-27T10:00:00+00'::timestamptz);
INSERT INTO public.posts (id, user_id, title, description, single_image_url, images, likes_count, comments_count, shares_count, is_sponsored, post_type, city, created_at, updated_at) VALUES ('a65e904e-2115-541b-b2cf-192efe2349f1'::uuid, '87fe685f-aabf-509d-aa55-ecadd782ca72'::uuid, '', 'Hajji & Associés, cabinet d''avocats d''affaires fondé par Amin Hajji en 1996, accompagne les ventes et les baux immobiliers ainsi que les investissements internationaux au Maroc.

La mission couvre l''audit des titres et des autorisations, la promesse, le contrat de vente et les baux, puis la coordination avec le notaire. Le cabinet intervient aussi en M&A, infrastructures et arbitrage.', 'https://ahlo.ma/wp-content/uploads/2022/06/Amin-Hajji-le-fondateur.jpg', '["https://ahlo.ma/wp-content/uploads/2022/06/Amin-Hajji-le-fondateur.jpg", "https://ahlo.ma/wp-content/uploads/2022/05/CABINET-D-AVOCAT-HAJJI-ASSOCIES-CASABLANCA-CABINET-AMIN-HAJJI-MISE-EN-AVANT.jpg", "https://ahlo.ma/wp-content/uploads/2022/04/CABINET-D-AVOCAT-HAJJI-ASSOCIES-CASABLANCA-TROPHEE-D-OR.png"]'::jsonb, 0, 0, 0, FALSE, 'standard', 'Casablanca', '2026-08-18T15:20:00+00'::timestamptz, '2026-08-18T15:20:00+00'::timestamptz);

